-- Gold Query
SELECT T2.School, T2.DOC FROM frpm AS T1 INNER JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode WHERE T2.FundingType = 'Locally funded' AND (T1."Enrollment (K-12)" - T1."Enrollment (Ages 5-17)") > (SELECT AVG(T3."Enrollment (K-12)" - T3."Enrollment (Ages 5-17)") FROM frpm AS T3 INNER JOIN schools AS T4 ON T3.CDSCode = T4.CDSCode WHERE T4.FundingType = 'Locally funded');

/*
Gold Result:
('Locally funded164', 'Locally funded182')
*/

-- Prediction Query
SELECT s.School, s.DOCType FROM frpm AS frp JOIN schools AS s ON frp.CDSCode = s.CDSCode WHERE (frp."Enrollment (K-12)" - frp."Enrollment (Ages 5-17)") > (SELECT AVG(enrollment_difference) FROM (SELECT (frp."Enrollment (K-12)" - frp."Enrollment (Ages 5-17)") AS enrollment_difference FROM frpm AS frp JOIN schools AS s ON frp.CDSCode = s.CDSCode WHERE s.FundingType = 'Locally funded')) AND s.FundingType = 'Locally funded';

